# -*- coding: utf-8 -*-
# Libro 11: Mantén encendido tu amor (Silk). Libro de relaciones en general, NO de crianza. Sin comillas: ideas de reseñas y de la descripcion de la editorial.
TARJ = "[sereno, cierre] "
RS = "Descripción de la editorial y reseñas (Heartspoken); sin vista previa en español, por eso no hay citas textuales"
C(11, 1, "Conexión, comunicación y límites", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Este libro no es solo de adolescentes. Pero sus ideas caben en tu casa."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Mantén encendido tu amor, de Danny Silk, es un libro de relaciones en general, no un manual de crianza. Su subtítulo resume la propuesta: conexión, comunicación y límites. Sus ideas se aplican a la pareja y a la familia. Por eso conviene leerlo completo y con ese contexto."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Según reseñas del libro, plantea que fuimos diseñados para la conexión, pero que muchas personas mantienen distancia por miedo a que las lastimen. Suena conocido, ¿verdad? Eso también le pasa a tu hijo. Y quizá a ti."),
 ("joven", "rewe", "[adolescente, bajito, cerrado] Mejor no digo nada. Así nadie me lastima."),
 ("papa", "mario", "[papá, cansado, honesto] Yo también me alejo cuando sé que va a haber pleito."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: fíjate si en algún momento te alejas de tu hijo para evitar un pleito o un dolor. Y acércate un poco más, solo por hoy. Un paso, no diez."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: qué significa realmente tener poder."),
], [
 ("titular", "gancho", "adolescentes", "No es solo de adolescentes", "Palabra «adolescentes» con una puerta que se abre a «familia»"),
 ("titular", "idea", "relaciones", "Un libro de relaciones en general", "«relaciones en general» en morado con subrayado amarillo"),
 ("icono", "idea", "subtítulo", "Conexión · Comunicación · Límites", "Tres íconos: hilo, globo de diálogo, línea de cancha"),
 ("icono", "giro", "conexión", "Diseñados para conectar", "Dos clavijas que encajan"),
 ("icono", "giro", "distancia", "Distancia por miedo", "Dos siluetas con una pared de cristal en medio"),
 ("reaccion", "joven", "nadie", "Mejor no digo nada. Así nadie me lastima.", "Burbuja del adolescente, tenue"),
 ("reaccion", "papa", "alejo", "Yo también me alejo cuando sé que va a haber pleito", "Burbuja de papá"),
 ("accion", "accion", "acércate", "Para hoy: acércate un poco más", "Tarjeta «Para hoy» con dos siluetas que se acercan un paso"),
 ("titular", "siguiente", "poder", "Siguiente: qué es tener poder", "Palabra «poder» con interrogación"),
], [RS])

C(11, 2, "Poder es dominio propio", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Controlar a tu hijo, o controlarte a ti?"),
 ("papa", "mario", "[papá, molesto, tajante] ¡Me vas a obedecer porque yo mando!"),
 ("joven", "rewe", "[adolescente, cerrado, bajito] Cuando me gritan, me cierro más."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Según las reseñas, el libro redefine el poder: no es controlar a los demás, sino hacerte responsable de quién eres y de cómo respondes. Así que la pregunta cambia. Ya no es: ¿cómo lo hago obedecer? Es: ¿cómo respondo yo?"),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Aplicado a la casa, cuando tu hijo te enoja, lo único que puedes dirigir por completo es tu propia reacción. Lo demás, no depende de ti. Eso no significa dejar de poner límites. Significa ponerlos sin perder el control de ti."),
 ("papa2", "mario", "[papá, tranquilo, firme] Estoy enojado. Dame un momento y lo hablamos."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: cuando tu hijo te haga enojar, haz una pausa y pregúntate: ¿lo estoy tratando de controlar a él, o me estoy controlando a mí? Respira. Cuenta hasta cinco."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: límites que cuidan la relación."),
], [
 ("titular", "gancho", "controlarte", "¿Controlarlo a él o controlarte a ti?", "Dos volantes: uno afuera, otro frente a una silueta, sin rostro"),
 ("reaccion", "papa", "mando", "¡Me vas a obedecer porque yo mando!", "Burbuja de papá en mayúsculas"),
 ("reaccion", "joven", "gritan", "Cuando me gritan, me cierro más", "Burbuja del adolescente, tenue"),
 ("titular", "idea", "poder", "Poder: dominio propio", "«dominio propio» en morado con subrayado amarillo"),
 ("icono", "idea", "responsable", "Responsable de quién eres y cómo respondes", "Espejo y una flecha de respuesta"),
 ("icono", "giro", "reacción", "Lo único que diriges por completo: tu reacción", "Una sola perilla que una mano gira"),
 ("reaccion", "papa2", "momento", "Estoy enojado. Dame un momento y lo hablamos.", "Burbuja de papá, tono sereno"),
 ("accion", "accion", "pausa", "Para hoy: pausa y pregunta", "Tarjeta «Para hoy» con símbolo de pausa"),
 ("titular", "accion", "controlando", "¿Lo controlo a él, o me controlo yo?", "Dos flechas: una apunta afuera, otra hacia adentro"),
 ("titular", "siguiente", "relación", "Siguiente: límites que cuidan la relación", "Cerco bajo con una puerta abierta"),
], [RS])

C(11, 3, "Límites que cuidan", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Un límite no es un muro."),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Según las reseñas, el libro propone que quien tiene dominio propio pone límites sanos. Y que esos límites ayudan al otro a hacerse responsable también. Es decir, tú te haces cargo de ti, y él de lo suyo."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Detrás está una idea de libertad con responsabilidad. Los límites cuidan la relación, no la rompen. Puede sonar duro, pero un límite sano se dice con calma."),
 ("papa", "mario", "[papá, tranquilo, firme] No te voy a gritar. Pero tampoco voy a permitir eso."),
 ("joven", "rewe", "[adolescente, bajito, sorprendido] Al menos me lo dijo sin explotar."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: piensa en un límite que quieres poner, y antes de decirlo, pregúntate: ¿esto cuida nuestra relación, o solo descarga mi enojo? Una frase. Un solo límite."),
 ("tarjeta", "marisol", TARJ + "Mantén encendido tu amor, de Danny Silk, en ediciones de Loving on Purpose y Buena Semilla. Es un libro de relaciones en general, y vale la pena leerlo completo. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "muro", "Un límite no es un muro", "Muro de ladrillos que se transforma en una cerca baja con puerta"),
 ("icono", "idea", "dominio", "Dominio propio → límites sanos", "Perilla que gira y una línea de cancha que se dibuja"),
 ("icono", "idea", "responsable", "El otro también se hace responsable", "Dos manos que sostienen la misma cuerda"),
 ("titular", "giro", "libertad", "Libertad con responsabilidad", "Dos palabras unidas por un hilo amarillo"),
 ("reaccion", "papa", "gritar", "No te voy a gritar. Pero tampoco voy a permitir eso.", "Burbuja de papá, tono firme"),
 ("reaccion", "joven", "explotar", "Al menos me lo dijo sin explotar", "Burbuja del adolescente"),
 ("accion", "accion", "límite", "Para hoy: un límite que cuida", "Tarjeta «Para hoy» con una palomita"),
 ("titular", "accion", "enojo", "¿Cuida la relación, o descarga mi enojo?", "Balanza con un corazón y una chispa"),
 ("tarjeta_libro", "tarjeta", "Buena Semilla", "Mantén encendido tu amor · Danny Silk · Loving on Purpose / Buena Semilla · Libro de relaciones en general", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [RS])
